# sliding GC 
w=100
vals=[]
for s in range(0,n-w+1,25):
    sub=seq[s:s+w]
    vals.append(((sub.count('G')+sub.count('C'))/w, s))
low=min(vals); high=max(vals)
print("GC window(100) min",low,"max",high)

# palindromes 12-17
pal=[]
K=12
seen={}
for i in range(n-K+1):
    seen.setdefault(seq[i:i+K],[]).append(i)
for k,v in seen.items():
    rk=rc(k)
    if rk!=k and rk in seen:
        pal.append((k,seen.get(rk)))
print("palindromic 12-mers:", len(pal))
for k,v in pal[:8]: print("  ",k, seen[k], seen[rc(k)])
# perfect palindromes (self revcomp) longer
print("self-revcomp (perfect palindrome) >=10:")
for K2 in (10,12,14):
    c=0
    for i in range(n-K2+1):
        if seq[i:i+K2]==rc(seq[i:i+K2]): 
            c+=1
            if c<=3: print("   ",K2,i,seq[i:i+K2])
    print("  K=",K2,"count",c)

# GC3 for ORF1/ORF2
def gc3(cds):
    c=cds[2::3]; g=cds[1::3]
    return (c.count('G')+c.count('C'))/len(c)
