import random
seq = "".join(l.strip() for l in open("region.fasta").read().splitlines()[1:])
n=len(seq)
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
stop=set(("TAA","TAG","TGA"))
def longest_orf(s):
    best=0
    for f in range(3):
        i=f;start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod in stop:
                if start is not None: best=max(best,i+3-start)
                start=None
            else:
                if start is None and cod=='ATG': start=i
            i+=3
        if start is not None: best=max(best,len(s)-start)
    return best
random.seed(0)
bases=list(seq)
sims=[]
for t in range(20):
    random.shuffle(bases)
    s="".join(bases)
    sims.append(max(longest_orf(s),longest_orf(rc(s))))
print("shuffled longest ORF (bp): min",min(sims),"max",max(sims),"mean",sum(sims)/len(sims))
print("observed longest ORF (bp):",max(longest_orf(seq),longest_orf(rc(seq))))
# and second longest observed
def orfs(s):
    out=[]
    for f in range(3):
